mapper.select:
select 
from audit_period_report r
        left join audit_subject s on r.subject_id = s.subject_id
        left join sys_user u on s.handler_id = u.user_id
where r.deleted = 0
and s.name like concat('%', #{subjectName}, '%')
and r.period_type = #{periodType}
and r.period_key = #{periodKey}
and r.generate_time >= #{beginTime}
and r.generate_time <= #{endTime}
order by r.period_end desc, r.report_id desc

select 
from audit_period_report r
        left join audit_subject s on r.subject_id = s.subject_id
        left join sys_user u on s.handler_id = u.user_id
where r.subject_id = #{subjectId}
  and r.period_type = #{periodType}
  and r.period_key = #{periodKey}
limit 1

mapper.update:
update audit_period_report
period_start = #{periodStart}, period_end = #{periodEnd}, budget_amount = #{budgetAmount}, income_amount = #{incomeAmount}, expense_amount = #{expenseAmount}, expense_by_category = #{expenseByCategory}, balance_end = #{balanceEnd}, loan_out_count = #{loanOutCount}, loan_unreturned = #{loanUnreturned}, generate_time = #{generateTime}, deleted = #{deleted}, update_by = #{updateBy}, update_time = now()
where report_id = #{reportId}

mapper.select:
select ifnull(sum(amount), 0)
from audit_fund_flow
where subject_id = #{subjectId}
  and flow_type = #{flowType}
  and deleted = 0


        and status = 'APPROVED'



        and status = 'APPROVED'


  and occur_date >= #{periodStart}
  and occur_date <= #{periodEnd}

select category, ifnull(sum(amount), 0) as total
from audit_fund_flow
where subject_id = #{subjectId}
  and flow_type = 'EXPENSE'
  and status = 'APPROVED'
  and deleted = 0
  and occur_date >= #{periodStart}
  and occur_date <= #{periodEnd}
group by category

select ifnull(count(*), 0)
from audit_loan
where subject_id = #{subjectId}
  and deleted = 0
  and borrow_date >= #{periodStart}
  and borrow_date <= #{periodEnd}

select ifnull(count(*), 0)
from audit_loan
where subject_id = #{subjectId}
  and deleted = 0
  and status in ('BORROWED', 'OVERDUE')
  and borrow_date <= #{periodEnd}
